\end{equation}
Since $f(x_k) - f(x_{k+1}) \leq F(x_k) - F(x_{k+1})$, we obtain:
\begin{equation}
\eta (F(x_{k+1}) - F(x^*)) + \frac{1}{2} \|x_{k+1} - x^*\|^2 \leq \eta (F(x_k) - F(x_{k+1}))
